def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    bob_bid = None
    david_bid = None
    urgent_opp = 0

    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if agent_id == 'Bob':
                    bob_bid = float(bid)
                elif agent_id == 'David':
                    david_bid = float(bid)

    if not alive:
        return max(0.0, min(budget, 18.0))

    scarcity = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))
    low_supply = supply <= 17.0
    high_supply = supply >= 22.0

    survival_mode = hp <= 2 or no_water_days >= 2
    caution_mode = hp <= 4 or no_water_days >= 1

    if prev_bids:
        highest_prev = max(prev_bids)
        second_prev = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev
    else:
        highest_prev = 0.0
        second_prev = 0.0

    if bob_bid is None:
        bob_bid = 65.0
    if david_bid is None:
        david_bid = 86.0

    if survival_mode:
        target = max(78.0, bob_bid + 3.0)
        if low_supply or urgent_opp >= 2:
            target = max(target, 88.0)
        return max(0.0, min(budget, target))

    if low_supply:
        if hp >= 6 and budget < 420:
            return max(0.0, min(budget, 8.0))
        target = bob_bid + 1.2
        if david_bid >= 86.0 and hp >= 5:
            target = min(target, 69.0)
        else:
            target = max(target, 74.0)
        return max(0.0, min(budget, target))

    if high_supply:
        target = max(52.0, min(69.5, bob_bid + 1.0))
        if urgent_opp == 0 and hp >= 6:
            target -= 3.0
        return max(0.0, min(budget, target))

    target = max(58.0, min(72.0, bob_bid + 1.5))
    if highest_prev >= 85.0 and hp >= 5:
        target = min(target, 68.0)
    if caution_mode:
        target = max(target, second_prev + 1.0, 72.0)
    if budget < 250 and hp >= 6:
        target = min(target, 60.0)

    return max(0.0, min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    supply = int(day_context['supply'])  # ensure integer
    day = int(day_context['day'])
    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # filter alive opponents
    alive_opps = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive_opps:
        # no competition, bid low to save
        return min(budget, DAILY_SALARY * 0.3)

    # collect previous bids from alive opponents
    prev_bids = []
    for opp in alive_opps.values():
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(float(trace['bid']))

    # base bid: if we have history, target slightly above max of yesterday's bids
    # else use heuristic
    if prev_bids:
        max_prev = max(prev_bids)
        # if we are desperate, match or beat
        if hp <= 2 or no_water_days >= 1:
            target = max(max_prev + 1, DAILY_SALARY * 0.85)
        else:
            target = max(max_prev + 0.5, DAILY_SALARY * 0.4)
    else:
        # no history: bid based on HP
        if hp <= 3:
            target = DAILY_SALARY * 0.9
        else:
            target = DAILY_SALARY * 0.5

    # ensure we don't overbid beyond budget
    bid = min(budget, target)
    # also ensure we don't exceed a reasonable cap (e.g., supply * salary? not needed but safe)
    # clamp to 0
    bid = max(0, bid)
    return bid
